from PIL import Image, ImageDraw, ImageOps
img = ImageOps.autocontrast(Image.open('radiograph.jpg').convert('L'), cutoff=1)
d = ImageDraw.Draw(img)
for x in range(0, 2473, 100):
    d.line([(x,0),(x,1252)], fill=128, width=1) if x%500 else d.line([(x,0),(x,1252)], fill=200, width=3)
for y in range(0, 1252, 100):
    d.line([(0,y),(2473,y)], fill=128, width=1) if y%500 else d.line([(0,y),(2473,y)], fill=200, width=3)
for x in range(0, 2473, 500):
    for y in range(0, 1252, 250):
        d.text((x+5, y+5), f"{x},{y}", fill=255)
img.save('/tmp/grid.png')
EOF", "description": "Overlay coordinate grid on radiograph"}

